SELECT City
FROM schools
WHERE CDSCode = '1611920113902';

SELECT School, EILName
FROM schools
WHERE CDSCode = '1612590136051';

SELECT COUNT(DISTINCT scryfallOracleId) AS card_count
FROM cards
WHERE ',' || promoTypes || ',' LIKE '%,release,%';

SELECT ROUND(100.0 * SUM(CASE WHEN CAST(strftime('%Y', Birthday) AS INTEGER) >= 1960 THEN 1 ELSE 0 END) / COUNT(*), 1) AS percentage
FROM Patient
WHERE Diagnosis LIKE '%psoriatic arthritis%';

SELECT COUNT(DISTINCT ID) AS patient_count
FROM Patient
WHERE LOWER(Diagnosis) LIKE '%psoriatic arthritis%';

SELECT ROUND(
  100.0 * SUM(
    CASE WHEN NOT EXISTS (
      SELECT 1
      FROM atom a
      WHERE a.molecule_id = m.molecule_id
        AND UPPER(a.element) = 'F'
    ) THEN 1 ELSE 0 END
  ) / NULLIF(COUNT(*), 0),
  2
) AS percentage_no_fluorine
FROM molecule m
WHERE m.label LIKE '%+%';
